def _expand_field_error_routes() -> dict[tuple[str, str, str], str]:
    routes: dict[tuple[str, str, str], str] = {}
    for route_id, profiles, fields, conditions, code in _FIELD_ERROR_ROUTE_ROWS:
        pairs = _QP if profiles == "QP" else tuple((profile, field) for profile in ("CDG" if profiles == "A" else profiles) for field in fields)
        if route_id == "R43":
            pairs = tuple((profile, field) for profile in "CDG" for field in _PROFILE_BOUND_FIELDS[profile])
        elif route_id == "R47":
            pairs = tuple((profile, "HEADER:" + field) for profile in "CDG" for field in _PROFILE_BOUND_FIELDS[profile])
        for profile, field in pairs:
            for condition in conditions:
                key = (_PROFILE_ID[profile], field, condition)
                if key in routes:
                    raise RuntimeError("duplicate contract route")
                routes[key] = code
    if len(_FIELD_ERROR_ROUTE_ROWS) != 47 or len(routes) != 317:
        raise RuntimeError("incomplete contract route closure")
    return routes


_FIELD_ERROR_ROUTE = _expand_field_error_routes()


def _field_route(profile_id: str, canonical_field: str, condition: str) -> str:
    code = _FIELD_ERROR_ROUTE.get((profile_id, canonical_field, condition))
    if code is None:
        raise ValueError("unroutable field condition")
    return code


def _source_cells_key(source_cells: tuple[SourceCellRefV1, ...]) -> tuple[tuple[object, ...], ...]:
    def key(cell: SourceCellRefV1) -> tuple[object, ...]:
        if type(cell.sheet_ref) is not str or re.fullmatch(r"S[0-9]{6}", cell.sheet_ref) is None:
            raise ValueError("invalid sheet identity")
        return (int(cell.sheet_ref[1:]), cell.row_index, cell.column_index,
                cell.authority_row_index, cell.authority_column_index,
                _VALUE_ORIGIN_ORDINAL[cell.value_origin], cell.cell_ref, cell.authority_cell_ref)
    return tuple(sorted({key(cell) for cell in source_cells}))


def _private_descriptor_total_key(descriptor: tuple[object, ...]) -> tuple[object, ...]:
    """Use the sealed descriptor identity for candidate ordering without atom expansion."""
    if descriptor == ():
        return ()
    context = _P5_REF_ARENA_CONTEXT.get()
    if type(context) is not tuple:
        raise ValueError("private evidence arena")
    if len(context) == 3:
        arena, _ref_ids, state = context
        base_state = state
    elif len(context) == 2:
        arena, base_state = context
    else:
        raise ValueError("private evidence arena")
    if type(arena) not in {list, tuple} or type(base_state) not in {dict, tuple}:
        raise ValueError("private evidence metadata closure")
    decoded = _private_descriptor_decoder(descriptor, len(arena), base_state, None)
    if decoded is None:
        raise ValueError("private evidence metadata closure")
    if decoded[0] == _TAG_REF:
        return (_TAG_REF, decoded[1])
    if decoded[0] == _TAG_SORTED_BASE:
        return (_TAG_SORTED_BASE, decoded[1])
    return (_TAG_BASE_PLUS_DELTA, decoded[1], decoded[3])


def _candidate_total_key(code: str, scope_instance: tuple[int | str, int | str, int | str, int | str, int | str], source_cells: tuple[object, ...], field: str | None = None) -> tuple[object, ...]:
    phase, rank, scope, expected_field, selector, origin = _ERROR_SPEC[code]
    resolved_field = expected_field if field is None else field
    if len(scope_instance) != 5 or any(type(item) is not int for item in scope_instance):
        raise ValueError("scope instance must be five exact integers")
    return (_PHASE_ORDINAL[phase], rank, _CODE_ORDINAL[code], _SCOPE_ORDINAL[scope], tuple(scope_instance), _FIELD_ORDINAL[resolved_field], _private_descriptor_total_key(source_cells), _ORIGIN_ORDINAL[origin], code)


@dataclass(frozen=True, slots=True)
class SourceCellRefV1:
    sheet_ref: str
    row_index: int
    column_index: int
    cell_ref: str
    authority_row_index: int
    authority_column_index: int
    authority_cell_ref: str
    value_origin: str


@dataclass(frozen=True, slots=True)
class _EvidenceAtom:
    """Validated private source identity retained until a public boundary."""
    sheet_ref: str
    row_index: int
    column_index: int
    cell_ref: str
    authority_row_index: int
    authority_column_index: int
    authority_cell_ref: str
    value_origin: str


def _private_source_identity(value: _EvidenceAtom | tuple) -> tuple[str, int, int, str, int, int, str, str]:
    """Close the exact private identity grammar before any public ref is built."""
    if type(value) is _EvidenceAtom:
        identity = (
            value.sheet_ref, value.row_index, value.column_index, value.cell_ref,
            value.authority_row_index, value.authority_column_index,
            value.authority_cell_ref, value.value_origin,
        )
    elif type(value) is tuple:
        identity = value
    else:
        raise ValueError("private evidence atom closure")
    if (len(identity) != 8 or type(identity[0]) is not str or type(identity[3]) is not str
            or type(identity[6]) is not str or type(identity[7]) is not str
            or any(type(part) is not int or part <= 0 for part in (identity[1], identity[2], identity[4], identity[5]))
            or re.fullmatch(r"S[0-9]{6}", identity[0]) is None
            or identity[3] != _a1(identity[1], identity[2])
            or identity[6] != _a1(identity[4], identity[5])
            or identity[7] not in _VALUE_ORIGIN_ORDINAL):
        raise ValueError("private evidence atom closure")
    merged = identity[7].startswith("MERGED_TOP_LEFT_")
    if ((not merged and identity[4:6] != identity[1:3])
            or (merged and (identity[4] > identity[1] or identity[5] > identity[2]))):
        raise ValueError("private evidence atom closure")
    return identity


def _public_ref(value: _EvidenceAtom | tuple) -> SourceCellRefV1:
    """Materialize one semantically closed private atom at the public boundary."""
    sheet_ref, row, column, cell_ref, authority_row, authority_column, authority_ref, origin = _private_source_identity(value)
    return SourceCellRefV1(sheet_ref, row, column, cell_ref, authority_row, authority_column, authority_ref, origin)


def _public_refs(values: tuple[_EvidenceAtom, ...]) -> tuple[SourceCellRefV1, ...]:
    if type(values) is not tuple:
        raise ValueError("private evidence atom closure")
    return tuple(sorted({_public_ref(value) for value in values}, key=lambda value: _source_cells_key((value,))))


def _private_descriptor_from_ids(
    ids: tuple[int, ...],
    arena: tuple[_EvidenceAtom, ...] | list[_EvidenceAtom],
    state: dict,
    *,
    force_base: bool = False,
    prefer_base_plus_delta: bool = False,
) -> tuple[object, ...]:
    """Create one closed compact descriptor while the private arena is mutable."""
    if state.get("sealed") is True:
        raise ValueError("private evidence arena sealed")
    bases = state.get("bases")
    base_lookup = state.get("base_lookup")
    if type(bases) is not list or type(base_lookup) is not dict:
        raise ValueError("private evidence arena closure")

    if not ids:
        base_id = base_lookup.get(())
        if base_id is None:
            base_id = len(bases)
            bases.append(((), *_compact_base_metadata(arena, ())))
            base_lookup[()] = base_id
            state["verified_bases"].add(base_id)
        descriptor: tuple[object, ...] = ("SORTED_BASE", base_id)
    elif len(ids) == 1 and not force_base:
        descriptor = ("REF", ids[0])
    else:
        if prefer_base_plus_delta and base_lookup.get(ids) is None:
            base_members = ids[:-1]
            base_id = base_lookup.get(base_members)
            if base_id is None:
                if state["base_memberships"] + len(base_members) > 20 * 200000:
                    raise ValueError("private evidence arena closure")
                base_id = len(bases)
                bases.append((base_members, *_compact_base_metadata(arena, base_members)))
                base_lookup[base_members] = base_id
                state["base_memberships"] += len(base_members)
                state["verified_bases"].add(base_id)
            descriptor = ("BASE_PLUS_DELTA", base_id, (ids[-1],))
        else:
            base_id = base_lookup.get(ids)
            if base_id is None:
                if state["base_memberships"] + len(ids) > 20 * 200000:
                    raise ValueError("private evidence arena closure")
                base_id = len(bases)
                bases.append((ids, *_compact_base_metadata(arena, ids)))
                base_lookup[ids] = base_id
                state["base_memberships"] += len(ids)
                state["verified_bases"].add(base_id)
            descriptor = ("SORTED_BASE", base_id)
    state["descriptor_count"] += 1
    if state["descriptor_count"] > 20 * 200000:
        raise ValueError("private evidence arena closure")
    return descriptor


def _compact_descriptor_as_base(descriptor: tuple[object, ...]) -> tuple[object, ...]:
    """Freeze one complete shared component base exactly once before row deltas."""
    context = _P5_REF_ARENA_CONTEXT.get()
    if type(context) is not tuple or len(context) != 3:
        raise ValueError("private evidence arena")
    arena, _ref_ids, state = context
    if type(arena) not in {tuple, list} or type(state) is not dict or state.get("sealed") is True:
        raise ValueError("private evidence arena closure")
    decoded = _private_descriptor_decoder(descriptor, len(arena), MappingProxyType(state), arena)
    if decoded is not None and decoded[0] == _TAG_SORTED_BASE:
        return descriptor
    if decoded is not None and decoded[0] == _TAG_BASE_PLUS_DELTA:
        ids = tuple(sorted((*decoded[2][0], *decoded[3])))
    else:
        ids = _compact_descriptor_ids_from_metadata(descriptor, arena, MappingProxyType(state))
    if len(ids) < 2:
        return descriptor
    return _private_descriptor_from_ids(ids, arena, state, force_base=True)


def _compact_base_plus_ref(base: tuple[object, ...], ref: tuple[object, ...]) -> tuple[object, ...]:
    """Attach a small verified row descriptor without re-unioning a component base."""
    context = _P5_REF_ARENA_CONTEXT.get()
    if type(context) is not tuple or len(context) != 3:
        raise ValueError("private evidence arena")
    arena, _ref_ids, state = context
    base_state = MappingProxyType(state)
    decoded_base = _private_descriptor_decoder(base, len(arena), base_state, arena)
    if decoded_base is None:
        if type(base) is tuple and len(base) == 2 and type(base[0]) is str and base[0] == _TAG_SORTED_BASE:
            raise ValueError("owner compact dependency closure")
        return _compact_descriptor_union(base, ref)
    if decoded_base[0] not in {_TAG_SORTED_BASE, _TAG_BASE_PLUS_DELTA}:
        return _compact_descriptor_union(base, ref)
    members = decoded_base[2][0]
    decoded_ref = _private_descriptor_decoder(ref, len(arena), base_state, arena)
    if decoded_ref is None:
        return _compact_descriptor_union(base, ref)
    if decoded_ref[0] == _TAG_REF:
        additions = (decoded_ref[1],)
    elif decoded_ref[0] == _TAG_SORTED_BASE:
        additions = decoded_ref[2][0]
    else:
        additions = tuple(sorted((*decoded_ref[2][0], *decoded_ref[3])))
    if len(additions) > 20 or any(ref_id not in range(len(arena)) for ref_id in additions):
        return _compact_descriptor_union(base, ref)
    prior_delta = () if decoded_base[0] == _TAG_SORTED_BASE else decoded_base[3]
    delta = tuple(
        ref_id for ref_id in sorted(set((*prior_delta, *additions)))
        if (position := bisect.bisect_left(members, ref_id)) == len(members) or members[position] != ref_id
    )
    if not delta:
        return (_TAG_SORTED_BASE, decoded_base[1])
    return (_TAG_BASE_PLUS_DELTA, decoded_base[1], delta)


def _private_evidence_descriptor(values: tuple[_EvidenceAtom, ...], *, empty_base: bool = False) -> tuple[object, ...]:
    """Intern private atoms in the call arena and return its only live descriptor form."""
    if any(type(value) is not _EvidenceAtom for value in values):
        raise ValueError("private evidence arena")
    evidence = tuple(sorted(set(values), key=lambda value: _source_cells_key((value,))))
    if not evidence and not empty_base:
        return ()
    context = _P5_REF_ARENA_CONTEXT.get()
    if type(context) is tuple and len(context) == 2:
        raise ValueError("private evidence arena sealed")
    if type(context) is not tuple or len(context) != 3:
        raise ValueError("private evidence arena")
    arena, ref_ids, state = context
    if type(arena) is list:
        if type(ref_ids) is not dict or type(state) is not dict or state.get("dynamic") is not True:
            raise ValueError("private evidence arena closure")
        source_keys = state.get("source_keys")
        if type(source_keys) is not list or len(source_keys) != len(arena):
            raise ValueError("private evidence metadata closure")
        for value in evidence:
            if value not in ref_ids:
                ref_ids[value] = len(arena)
                arena.append(value)
                source_keys.append(_source_cells_key((value,))[0])
    elif type(arena) is tuple:
        if (type(state) is not dict or type(state.get("source_keys")) is not tuple
                or len(state["source_keys"]) != len(arena)):
            raise ValueError("private evidence arena closure")
    else:
        raise ValueError("private evidence arena closure")
    try:
        ids = tuple(sorted(ref_ids[value] for value in evidence))
    except (KeyError, TypeError) as error:
        raise ValueError("private evidence arena membership") from error
    if len(ids) != len(set(ids)):
        raise ValueError("private evidence arena closure")
    return _private_descriptor_from_ids(ids, arena, state)


def _private_descriptor_atoms(descriptor: tuple[object, ...]) -> tuple[_EvidenceAtom | tuple, ...]:
    """Resolve a compact descriptor only when its selected failure needs public refs."""
    if descriptor == ():
        return ()
    context = _P5_REF_ARENA_CONTEXT.get()
    if type(context) is not tuple:
        raise ValueError("private evidence arena")
    if len(context) == 3:
        arena, _ref_ids, state = context
        base_state = MappingProxyType(state)
    elif len(context) == 2:
        arena, base_state = context
    else:
        raise ValueError("private evidence arena")
    if type(arena) not in {tuple, list}:
        raise ValueError("private evidence arena closure")
    atoms = tuple(arena)
    ids = _compact_descriptor_ids_from_metadata(descriptor, atoms, base_state)
    return tuple(atoms[ref_id] for ref_id in ids)


@dataclass(frozen=True, slots=True)
class _Candidate:
    code: str
    field: str
    profile_id: str | None
    anchor_profile_id: str | None
    source_cells: tuple[object, ...]
    scope_instance: tuple[int, int, int, int, int]


def _scope_zero(code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None, **_context: object) -> tuple[int, int, int, int, int]:
    return (0, 0, 0, 0, 0)


def _scope_anchor_cell(source_cells: tuple[_EvidenceAtom, ...]) -> _EvidenceAtom:
    if not source_cells:
        raise ValueError("addressable scope requires evidence")
    cell = min(source_cells, key=lambda value: _source_cells_key((value,)))
    if type(cell.sheet_ref) is not str or re.fullmatch(r"S[0-9]{6}", cell.sheet_ref) is None:
        raise ValueError("invalid sheet identity")
    return cell


def _scope_sheet(code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None, **_context: object) -> tuple[int, int, int, int, int]:
    return (int(_scope_anchor_cell(source_cells).sheet_ref[1:]), 0, 0, 0, 0)


def _scope_profile(code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None, **_context: object) -> tuple[int, int, int, int, int]:
    cell = _scope_anchor_cell(source_cells)
    if anchor_profile_id not in _PROFILES:
        raise ValueError("profile scope requires bound profile")
    return (int(cell.sheet_ref[1:]), cell.row_index, 0, _PROFILES.index(anchor_profile_id), 0)


def _scope_header(code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None,
                  *, scope_cells: tuple[_EvidenceAtom, ...] = (), **_context: object) -> tuple[int, int, int, int, int]:
    cell = _scope_anchor_cell(scope_cells or source_cells)
    return (int(cell.sheet_ref[1:]), cell.row_index, cell.column_index, 0, 0)


def _scope_cell(code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None, **_context: object) -> tuple[int, int, int, int, int]:
    cell = _scope_anchor_cell(source_cells)
    return (int(cell.sheet_ref[1:]), cell.row_index, cell.column_index, cell.authority_row_index, cell.authority_column_index)


def _scope_carton_group(code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None,
                        *, provisional_owner: tuple[int, int, int, int, int, int, int, int, int] | None = None,
                        provisional_descriptors: tuple[tuple[int, int, int, int, int, int, int, int, int], ...] = (),
                        **_context: object) -> tuple[int, int, int, int, int]:
    if provisional_owner is not None:
        if provisional_owner not in provisional_descriptors:
            raise ValueError("unknown provisional carton owner")
        return _p5_provisional_scopes(provisional_descriptors)[provisional_owner]
    cell = _scope_anchor_cell(source_cells)
    return (int(cell.sheet_ref[1:]), cell.authority_row_index, cell.authority_column_index, 0, 0)


def _scope_aggregate_load_unit_group(code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None,
                                     *, provisional_owner: tuple[int, int, int, int, int, int, int, int, int] | None = None,
                                     provisional_descriptors: tuple[tuple[int, int, int, int, int, int, int, int, int], ...] = (),
                                     **_context: object) -> tuple[int, int, int, int, int]:
    if provisional_owner is not None:
        if provisional_owner not in provisional_descriptors:
            raise ValueError("unknown provisional aggregate owner")
        return _p5_provisional_scopes(provisional_descriptors)[provisional_owner]
    cell = _scope_anchor_cell(source_cells)
    return (int(cell.sheet_ref[1:]), cell.authority_row_index, cell.authority_column_index, 1, 0)


def _scope_duplicate_value(code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None, **_context: object) -> tuple[int, int, int, int, int]:
    if not source_cells:
        raise ValueError("duplicate scope requires evidence")
    first_row = min(cell.row_index for cell in source_cells)
    values = tuple(cell for cell in source_cells if cell.row_index > first_row)
    target = min(values or source_cells, key=lambda cell: _source_cells_key((cell,)))
    if type(target.sheet_ref) is not str or re.fullmatch(r"S[0-9]{6}", target.sheet_ref) is None:
        raise ValueError("invalid sheet identity")
    return (int(target.sheet_ref[1:]), target.row_index, target.column_index, 0, 0)


def _scope_row_value(code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None, **_context: object) -> tuple[int, int, int, int, int]:
    if not source_cells:
        raise ValueError("row scope requires evidence")
    source_row = max(cell.row_index for cell in source_cells)
    target = min((cell for cell in source_cells if cell.row_index == source_row), key=lambda cell: _source_cells_key((cell,)))
    if type(target.sheet_ref) is not str or re.fullmatch(r"S[0-9]{6}", target.sheet_ref) is None:
        raise ValueError("invalid sheet identity")
    return (int(target.sheet_ref[1:]), target.row_index, target.column_index, 0, 0)


_SCOPE_BY_NAME = {
    "input": _scope_zero,
    "workbook": _scope_zero,
    "sheet": _scope_sheet,
    "profile": _scope_profile,
    "header": _scope_header,
    "row": _scope_row_value,
    "cell": _scope_cell,
    "carton_group": _scope_carton_group,
    "aggregate_load_unit_group": _scope_aggregate_load_unit_group,
    "ir": _scope_zero,
    "result": _scope_zero,
}


def _scope_route(code: str, resolver: Callable[..., tuple[int, int, int, int, int]]) -> Callable[..., tuple[int, int, int, int, int]]:
    def route(actual_code: str, source_cells: tuple[_EvidenceAtom, ...], anchor_profile_id: str | None = None,
              *, provisional_owner: tuple[int, int, int, int, int, int, int, int, int] | None = None,
              provisional_descriptors: tuple[tuple[int, int, int, int, int, int, int, int, int], ...] = (),
              scope_cells: tuple[_EvidenceAtom, ...] = ()) -> tuple[int, int, int, int, int]:
        if actual_code != code:
            raise ValueError("scope route code mismatch")
        return resolver(code, source_cells, anchor_profile_id, provisional_owner=provisional_owner,
                        provisional_descriptors=provisional_descriptors, scope_cells=scope_cells)
    return route


_SCOPE_ANCHOR_BY_CODE = {
    code: _scope_route(code, _scope_by_name)
    for code, (_phase, _rank, scope_name, _field, _selector, _origin) in _ERROR_SPEC.items()
    for _scope_by_name in (_SCOPE_BY_NAME[scope_name],)
}
for _duplicate_code in ("SERIAL_DUPLICATE", "METADATA_LINE_NO_DUPLICATE"):
    _SCOPE_ANCHOR_BY_CODE[_duplicate_code] = _scope_route(_duplicate_code, _scope_duplicate_value)
_SCOPE_ANCHOR_BY_CODE["DIMENSION_SOURCE_CONFLICT"] = _scope_route("DIMENSION_SOURCE_CONFLICT", _scope_header)


def _candidate(code: str, field: str, source_cells: tuple[_EvidenceAtom, ...] = (), profile_id: str | None = None,
               anchor_profile_id: str | None = None, *,
               provisional_owner: tuple[int, int, int, int, int, int, int, int, int] | None = None,
               provisional_descriptors: tuple[tuple[int, int, int, int, int, int, int, int, int], ...] = (),
                scope_cells: tuple[_EvidenceAtom, ...] = (),
                source_descriptor: tuple[object, ...] | None = None) -> _Candidate:
    phase, _rank, _scope, expected_field, selector, selector_origin = _ERROR_SPEC[code]
    if selector_origin not in _SELECTOR_ORIGIN_COMPATIBILITY.get(selector, ()):
        raise ValueError("selector origin incompatible")
    if not expected_field.startswith("$") and field != expected_field:
        raise ValueError("literal contract field mismatch")
    if field not in _FIELD_ORDINAL:
        raise ValueError("unresolved contract field")
    if expected_field == "$CANDIDATE_INPUT" and (anchor_profile_id not in _PROFILE_SHORT or field not in _PROFILE_BOUND_FIELDS[_PROFILE_SHORT[anchor_profile_id]]):
        raise ValueError("invalid candidate input")
    if expected_field == "$BOUND_INPUT" and (anchor_profile_id not in _PROFILE_SHORT or field not in _PROFILE_BOUND_FIELDS[_PROFILE_SHORT[anchor_profile_id]]):
        raise ValueError("invalid bound input")
    if expected_field == "$BOUND_DIMENSION_INPUT" and field not in {"CARTON_LENGTH", "CARTON_WIDTH", "CARTON_HEIGHT", "CARTON_DIMENSIONS", "AGGREGATE_LOAD_UNIT_ENVELOPE", "HELPER_DIMENSION_RUN"}:
        raise ValueError("invalid bound dimension input")
    if expected_field == "$BOUND_SUMMARY_TOTAL_INPUT" and field not in {"DECLARED_TOTAL_CTNS", "DECLARED_TOTAL_NET_WEIGHT", "DECLARED_TOTAL_GROSS_WEIGHT", "TOTAL_CBM", "AGGREGATE_LOAD_UNIT_CBM"}:
        raise ValueError("invalid bound summary total input")
    if source_descriptor is not None:
        if source_cells or scope_cells or selector == "NONE":
            raise ValueError("private evidence arena")
        context = _P5_REF_ARENA_CONTEXT.get()
        if type(context) is not tuple:
            raise ValueError("private evidence arena")
        if len(context) == 3:
            arena, _ref_ids, base_state = _private_owner_arena(sealed=False)
        elif len(context) == 2:
            arena, base_state = _private_owner_arena(sealed=True)
        else:
            raise ValueError("private evidence arena")
        if (_compact_dependency_metadata(source_descriptor, arena, base_state) is None
                or selector_origin == "FORMULA_UNAVAILABLE_FACTS"):
            raise ValueError("private evidence arena")
        evidence = ()
        scope_evidence = ()
    else:
        if any(type(value) is not _EvidenceAtom for value in (*source_cells, *scope_cells)):
            raise ValueError("private evidence arena")
        evidence = tuple(sorted(set(source_cells), key=lambda value: _source_cells_key((value,))))
        scope_evidence = tuple(sorted(set(scope_cells), key=lambda value: _source_cells_key((value,))))
    if scope_evidence:
        if code not in {"HEADER_ALIAS_COLLISION", "PROFILE_AMBIGUOUS", "HEADER_ROW_AMBIGUOUS"}:
            raise ValueError("scope facts are not valid for code")
        if any(value not in evidence for value in scope_evidence):
            raise ValueError("scope facts must be frozen evidence")
    if selector == "NONE" and evidence:
        raise ValueError("NONE selector requires empty evidence")
    if selector != "NONE" and not evidence and source_descriptor is None:
        raise ValueError("non-NONE selector requires evidence")
    if selector == "EXPECTED_CELL" and len(evidence) != 1:
        raise ValueError("EXPECTED_CELL requires one present fact")
    if (selector == "ALL_SAME_COORDINATE"
            and len({(value.sheet_ref, value.row_index, value.column_index) for value in evidence}) != 1):
        raise ValueError("ALL_SAME_COORDINATE requires one coordinate")
    if (selector == "ALL_SAME_SHEET_ROW_HIDDEN_CONFLICTS"
            and (len(evidence) < 2 or len({(value.sheet_ref, value.row_index) for value in evidence}) != 1)):
        raise ValueError("hidden-row conflict requires one sheet row")
    if (selector == "ALL_SAME_SHEET_COLUMN_HIDDEN_CONFLICTS"
            and (len(evidence) < 2 or len({(value.sheet_ref, value.column_index) for value in evidence}) != 1)):
        raise ValueError("hidden-column conflict requires one sheet column")
    if phase == "P1_RAW_CELL_GRAMMAR" and any(value.value_origin != "UNVALIDATED_CELL" for value in evidence):
        raise ValueError("P1 evidence requires UNVALIDATED_CELL")
    if phase not in {"P0_INTAKE_IDENTITY", "P1_RAW_CELL_GRAMMAR"} and any(value.value_origin == "UNVALIDATED_CELL" for value in evidence):
        raise ValueError("validated phase evidence cannot be UNVALIDATED_CELL")
    if selector_origin == "FORMULA_UNAVAILABLE_FACTS" and not any(value.value_origin in {"FORMULA_UNAVAILABLE", "MERGED_TOP_LEFT_FORMULA_UNAVAILABLE"} for value in evidence):
        raise ValueError("formula unavailable evidence requires an unavailable value")
    if selector == "HEADER_AND_CELL" and len(evidence) < 2:
        raise ValueError("HEADER_AND_CELL requires header and value facts")
    if selector in {"ALL_DUPLICATE_FIELD_CELLS", "ADJACENT_FIELD_PAIR"} and len(evidence) < 3:
        raise ValueError(f"{selector} requires a header and two values")
    if selector == "MERGE_ANCHOR_AND_MEMBERS" and len(evidence) < 2:
        raise ValueError("MERGE_ANCHOR_AND_MEMBERS requires a complete component")
    resolved_scope = _SCOPE_ANCHOR_BY_CODE[code](code, evidence, anchor_profile_id,
                                                   provisional_owner=provisional_owner,
                                                   provisional_descriptors=provisional_descriptors,
                                                   scope_cells=scope_evidence)
    if len(resolved_scope) != 5 or any(type(value) is not int for value in resolved_scope):
        raise ValueError("scope instance must be five exact integers")
    return _Candidate(code, field, profile_id, anchor_profile_id,
                      source_descriptor if source_descriptor is not None else _private_evidence_descriptor(evidence), resolved_scope)


def _route_candidate(profile_id: str, canonical_field: str, condition: str,
                     source_cells: tuple[_EvidenceAtom, ...], *, header_state: bool = False,
                     provisional_owner: tuple[int, int, int, int, int, int, int, int, int] | None = None,
                     provisional_descriptors: tuple[tuple[int, int, int, int, int, int, int, int, int], ...] = ()) -> _Candidate:
    route_field = "HEADER:" + canonical_field if header_state else canonical_field
    code = _field_route(profile_id, route_field, condition)
    phase = _ERROR_SPEC[code][0]
    if phase not in {"P3_PROFILE_BIND", "P4_ROW", "P5_GROUP_DERIVATION"}:
        raise ValueError("route phase mismatch")
    expected_field = _ERROR_SPEC[code][3]
    field = "HEADER" if header_state else (expected_field if not expected_field.startswith("$") else canonical_field)
    return _candidate(code, field, source_cells, None if phase == "P3_PROFILE_BIND" else profile_id, profile_id,
                      provisional_owner=provisional_owner, provisional_descriptors=provisional_descriptors)


def _select_candidate(candidates: list[_Candidate]) -> _Candidate:
    canonical: dict[tuple[object, ...], _Candidate] = {}
    for candidate in candidates:
        key = _candidate_total_key(candidate.code, candidate.scope_instance, candidate.source_cells, candidate.field)
        if key in canonical and canonical[key] != candidate:
            raise ValueError("candidate payload collision")
        canonical[key] = candidate
    return canonical[min(canonical)]


def _candidate_failure(candidate: _Candidate) -> TranslationResultV1:
    return _failure(_ERROR_SPEC[candidate.code][0], candidate.code, _ERROR_SPEC[candidate.code][2], candidate.field,
                    candidate.profile_id, _private_descriptor_atoms(candidate.source_cells))


def _p5_candidate(code: str, field: str, profile_id: str,
                  source_cells: tuple[_EvidenceAtom, ...], *,
                  provisional_owner: tuple[int, int, int, int, int, int, int, int, int] | None = None,
                  provisional_descriptors: tuple[tuple[int, int, int, int, int, int, int, int, int], ...] = ()) -> _Candidate:
    return _candidate(code, field, source_cells, profile_id, profile_id,
                      provisional_owner=provisional_owner, provisional_descriptors=provisional_descriptors)


def _p5_descriptor_candidate(code: str, field: str, profile_id: str,
                             source_descriptor: tuple[object, ...], *,
                             provisional_owner: tuple[int, int, int, int, int, int, int, int, int] | None = None,
                             provisional_descriptors: tuple[tuple[int, int, int, int, int, int, int, int, int], ...] = ()) -> _Candidate:
    """Freeze a shared P5 evidence base without transient atom reconstruction."""
    return _candidate(code, field, (), profile_id, profile_id,
                      provisional_owner=provisional_owner, provisional_descriptors=provisional_descriptors,
                      source_descriptor=source_descriptor)


def _global_helper_resolution(cells: tuple[_Cell, ...], header_row: int, source_rows: tuple[int, ...],
                              headers: dict[str, _Cell], bound: dict[str, _Cell | None],
                              header_states: dict[int, str],
                              carton_descriptors: dict[tuple[str, int, int], tuple[int, int, int, int, int, int, int, int, int]],
                              provisional_descriptors: tuple[tuple[int, int, int, int, int, int, int, int, int], ...],
                              authority_cells: Mapping[tuple[str, int, int], tuple[_Cell, ...]] | None = None) -> tuple[dict[tuple[int, int, int, int, int, int, int, int, int], tuple[tuple[Decimal, Decimal, Decimal], tuple[object, ...]]], list[_Candidate]]:
    """Resolve only group-local blank-header helper runs for the global profile."""
    profile = "global_packing_explicit_semantics.v1"
    header_by_column = {cell.column: cell for cell in cells if cell.row == header_row}
    cells_by_row: dict[int, dict[int, _Cell]] = {}
    for cell in cells:
        cells_by_row.setdefault(cell.row, {})[cell.column] = cell
    groups: dict[tuple[int, int, int, int, int, int, int, int, int], list[tuple[int, dict[int, _Cell]]]] = {}
    serial_header = bound["serial"]
    count_header = bound["count"]
    if serial_header is None or count_header is None:
        raise ValueError("global helper requires bound serial and carton count")
    for row_number in source_rows:
        by_column = cells_by_row.get(row_number, {})
        serial_cell = _value(by_column, serial_header)
        if serial_cell is not None and _header(serial_cell) in {"total", "合计", "总计"}:
            continue
        count_cell = _value(by_column, count_header)
        if count_cell is None:
            continue
        owner_key = (count_cell.sheet_ref, count_cell.authority_row, count_cell.authority_column)
        descriptor = carton_descriptors.get(owner_key)
        if descriptor is None:
            raise ValueError("global helper owner is not provisional")
        groups.setdefault(descriptor, []).append((row_number, by_column))
    dimensions: dict[tuple[int, int, int, int, int, int, int, int, int], tuple[tuple[Decimal, Decimal, Decimal], tuple[object, ...]]] = {}
    candidates: list[_Candidate] = []
    for descriptor, members in sorted(groups.items()):
        member_rows = sorted({row for row, _by_column in members})
        member_cells = tuple(cell for row in member_rows for cell in cells_by_row.get(row, {}).values())
        row_cells = tuple(cell for cell in member_cells if _structural(cell))
        universe = tuple(sorted({cell.column for cell in row_cells}))
        helper_columns = tuple(
            column for column in universe
            if header_states.get(column, "BLANK_HEADER") == "BLANK_HEADER"
        )
        first_row, first_by_column = min(members, key=lambda item: item[0])
        serial_cell = _value(first_by_column, serial_header)
        if serial_cell is None:
            raise ValueError("global helper serial anchor missing")
        partition_cells: list[_Cell | None] = [serial_cell]
        data_by_column: dict[int, tuple[_Cell, ...]] = {}
        for column in helper_columns:
            values = tuple(cell for cell in row_cells if cell.column == column)
            data_by_column[column] = values
            partition_cells.append(header_by_column.get(column))
            partition_cells.extend(values)
        partition = _refs(*partition_cells)
        count_cells = tuple(_value(by_column, count_header) for _row, by_column in members)
        count_refs = _refs(count_header, *count_cells)
        group_rows = {row for row, _by_column in members}
        topology_fields = ("model", "qty", "count", "pallet", "envelope", "dimensions", "length", "width", "height", "net", "gross")
        topology_cells = tuple(
            cell for name in topology_fields for cell in (bound.get(name),)
        ) + tuple(
            cell for _row, by_column in members for name in topology_fields for cell in (_value(by_column, bound.get(name)),)
        )
        count_anchor = next((cell for cell in count_cells if cell is not None), None)
        count_component: tuple[_Cell, ...] = ()
        if count_anchor is not None:
            if authority_cells is not None:
                count_component = authority_cells.get(
                    (count_anchor.sheet_ref, count_anchor.authority_row, count_anchor.authority_column), (),
                )
            else:
                count_component = tuple(
                    cell for cell in cells
                    if (cell.sheet_ref, cell.authority_row, cell.authority_column)
                    == (count_anchor.sheet_ref, count_anchor.authority_row, count_anchor.authority_column)
                )
            if {cell.row for cell in count_component} != group_rows:
                candidates.append(_p5_candidate(
                    "GROUP_SPAN_CONFLICT", "CARTON_GROUP_SPAN", profile,
                    _refs(*topology_cells, *count_component), provisional_owner=descriptor,
                    provisional_descriptors=provisional_descriptors,
                ))
                continue
        total_cbm_header = bound.get("total_cbm")
        total_cbm_cells = tuple(_value(by_column, total_cbm_header) for _row, by_column in members)
        nonblank_cbm = tuple(cell for cell in total_cbm_cells if cell is not None and cell.value not in (None, ""))
        cbm_component: tuple[_Cell, ...] = ()
        if total_cbm_header is not None and nonblank_cbm:
            declaration_components = {
                (value.sheet_ref, value.authority_row, value.authority_column)
                for value in nonblank_cbm
            }
            if len(declaration_components) != 1:
                candidates.append(_p5_candidate("GROUP_SPAN_CONFLICT", "CARTON_GROUP_SPAN", profile,
                                                _refs(total_cbm_header, *nonblank_cbm), provisional_owner=descriptor,
                                                provisional_descriptors=provisional_descriptors))
                continue
            authority = next(iter(declaration_components))
            cbm_component = tuple(cell for cell in cells if (cell.sheet_ref, cell.authority_row, cell.authority_column) == authority)
            if {cell.row for cell in cbm_component} != group_rows:
                candidates.append(_p5_candidate("GROUP_SPAN_CONFLICT", "CARTON_GROUP_SPAN", profile,
                                                _refs(total_cbm_header, *cbm_component), provisional_owner=descriptor,
                                                provisional_descriptors=provisional_descriptors))
                continue
        if any(bound.get(name) is not None for name in ("dimensions", "length", "width", "height")):
            if helper_columns:
                candidates.append(_p5_candidate("HELPER_DIMENSION_RUN_AMBIGUOUS", "HELPER_DIMENSION_RUN", profile, partition,
                                                provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        envelopes = tuple(_value(by_column, bound.get("envelope")) for _row, by_column in members)
        if any(cell is None or _packing(cell) != "loose" for cell in envelopes):
            candidates.append(_p5_candidate("HELPER_DIMENSION_RUN_REQUIRED", "HELPER_DIMENSION_RUN", profile, partition,
                                            provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        runs: list[tuple[int, ...]] = []
        for column in helper_columns:
            if not runs or column != runs[-1][-1] + 1:
                runs.append((column,))
            else:
                runs[-1] += (column,)
        eligible = [
            run for run in runs
            if len(run) == 3 and any(
                all(
                    len(data_by_column[column]) == 1
                    and data_by_column[column][0].row == row
                    and not data_by_column[column][0].value_origin.startswith("MERGED")
                    for column in run
                )
                for row in member_rows
            )
        ]
        if not eligible:
            candidates.append(_p5_candidate("HELPER_DIMENSION_RUN_REQUIRED", "HELPER_DIMENSION_RUN", profile, partition,
                                            provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        if len(eligible) > 1:
            candidates.append(_p5_candidate("HELPER_DIMENSION_RUN_AMBIGUOUS", "HELPER_DIMENSION_RUN", profile, partition,
                                            provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        run = eligible[0]
        if set(run) != set(helper_columns):
            candidates.append(_p5_candidate("UNEXPECTED_HELPER_FACT", "HELPER_DIMENSION_RUN", profile, partition,
                                            provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        run_cells: list[_Cell | None] = []
        for column in run:
            run_cells.append(header_by_column.get(column))
            run_cells.extend(data_by_column[column])
        if total_cbm_header is None:
            cbm_refs = _refs(*headers.values())
        elif not any(cell is not None and cell.value not in (None, "") for cell in total_cbm_cells):
            cbm_refs = _refs(total_cbm_header, serial_cell, *total_cbm_cells)
        else:
            cbm_refs = _refs(total_cbm_header, *cbm_component)
        run_dependencies = tuple(sorted(set(_refs(*run_cells) + count_refs + cbm_refs), key=lambda value: _source_cells_key((value,))))
        unavailable = tuple(cell for cell in (cell for column in run for cell in data_by_column[column]) if cell.value is _UNAVAILABLE)
        if unavailable:
            candidates.append(_route_candidate(profile, "HELPER_DIMENSION_RUN", "FORMULA_UNAVAILABLE", run_dependencies,
                                               provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        token_overflow = tuple(cell for column in run for cell in data_by_column[column]
                               if type(cell.value) is str and _utf8_length(cell.value, 256) > 256)
        if token_overflow:
            candidates.append(_p5_candidate("HELPER_NUMERIC_TOKEN_BUDGET_EXCEEDED", "RESOURCE_HELPER_NUMERIC_TOKEN", profile,
                                            run_dependencies, provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        parsed: list[Decimal] = []
        invalid_condition: str | None = None
        for column in run:
            values = data_by_column[column]
            if len(values) != 1:
                invalid_condition = "MISSING_VALUE"
                break
            value = values[0].value
            decimal = _decimal(value)
            if value in (None, ""):
                invalid_condition = "MISSING_VALUE"
                break
            if decimal is None:
                invalid_condition = "SYNTAX" if type(value) is str else "TYPE"
                break
            if decimal <= 0:
                invalid_condition = "RANGE"
                break
            parsed.append(decimal)
        if invalid_condition is not None:
            candidates.append(_route_candidate(profile, "HELPER_DIMENSION_RUN", invalid_condition, run_dependencies,
                                               provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        count = _positive_int(None if count_cells[0] is None else count_cells[0].value)
        if count is None:
            raise ValueError("P4 declared-carton-count preflight bypass")
        count_tuple = Decimal(count).as_tuple()
        derived_digits = len(count_tuple.digits) + sum(len(value.as_tuple().digits) for value in parsed)
        derived_exponent = count_tuple.exponent + sum(value.as_tuple().exponent + 1 for value in parsed)
        if derived_digits > 512 or not -512 <= derived_exponent <= 512:
            candidates.append(_p5_candidate("DERIVED_NUMERIC_BUDGET_EXCEEDED", "RESOURCE_NUMERIC", profile,
                                            run_dependencies, provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        parsed = [_shift_decimal(value, 1) for value in parsed]
        if not nonblank_cbm:
            candidates.append(_route_candidate(profile, "TOTAL_CBM", "HELPER_DEPENDENCY_MISSING", run_dependencies,
                                               provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        total_cbm = _decimal(nonblank_cbm[0].value)
        if count is None or total_cbm is None:
            raise ValueError("P4 total-cbm preflight bypass")
        expected_cbm = _shift_decimal(_multiply_decimal(count, *parsed), -9)
        if not _within_cargo_tolerance(total_cbm, expected_cbm):
            candidates.append(_p5_candidate("HELPER_DIMENSION_CBM_CROSSCHECK_FAILED", "TOTAL_CBM", profile, run_dependencies,
                                            provisional_owner=descriptor, provisional_descriptors=provisional_descriptors))
            continue
        dimensions[descriptor] = (
            (parsed[0], parsed[1], parsed[2]),
            _private_evidence_descriptor(run_dependencies),
        )
    return dimensions, candidates


