@dataclass(frozen=True, slots=True)
class _DecimalSnapshot:
    """Private, copied Decimal ABI facts; never retain an input Decimal."""
    sign: int
    digits: bytes
    exponent: int


@dataclass(frozen=True, slots=True, eq=False)
class _TemporalSnapshot:
    """P1 temporal ABI: tag, primitive components, fold, signed offset micros."""
    tag: str
    components: tuple[int, ...]
    fold: int
    offset_microseconds: int | None

    def __eq__(self, other: object) -> bool:
        if type(other) is _TemporalSnapshot:
            return (
                self.tag, self.components, self.fold, self.offset_microseconds,
            ) == (
                other.tag, other.components, other.fold, other.offset_microseconds,
            )
        # The private snapshot boundary retains the former detached-scalar
        # comparison behavior without retaining or reconstructing a temporal
        # object.  This only reads a caller-supplied exact temporal scalar.
        if self.tag == "date" and type(other) is date:
            return self.components == (
                date.year.__get__(other, date), date.month.__get__(other, date), date.day.__get__(other, date),
            )
        return NotImplemented

    def __hash__(self) -> int:
        return hash((self.tag, self.components, self.fold, self.offset_microseconds))


# Snapshot construction is intentionally patchable only through this concrete
# type; P1 must not accept a lookalike object with unconsumed temporal state.
_TEMPORAL_SNAPSHOT_TYPE = _TemporalSnapshot


@dataclass(frozen=True, slots=True)
class _OwnerBuildState:
    """Frozen private raw facts held until one public owner materialization."""
    values: MappingProxyType
    profile_id: str = ""
    owner_kind: str = ""
    structural_states: tuple[tuple[str, str], ...] = ()
    atomic_inventory: tuple[tuple[str, str, tuple[object, ...]], ...] = ()
    freeze_digest: bytes = b""

    def __post_init__(self) -> None:
        """Validate the one-way raw record before public materialization."""
        if not self.atomic_inventory:
            return
        names = tuple(item[0] for item in self.atomic_inventory)
        if len(names) != len(set(names)) or tuple(sorted(names)) != names:
            raise ValueError("owner atomic inventory closure")
        arena, _ref_ids, base_state = _private_owner_arena(sealed=False)
        if any(
            type(name) is not str or not name or type(state) is not str
            or _compact_dependency_metadata(descriptor, arena, base_state) is None
            for name, state, descriptor in self.atomic_inventory
        ):
            raise ValueError("owner atomic inventory closure")
        if not self.structural_states:
            raise ValueError("owner structural state closure")
        # The freeze digest is captured once at construction; the plan chain
        # re-derives it per owner and any post-freeze mutation fails closed.
        object.__setattr__(self, "freeze_digest", _owner_inventory_digest(
            self.profile_id, self.owner_kind, self.structural_states, self.atomic_inventory,
        ))


_OWNER_BUILD_STATE_TYPE = _OwnerBuildState


@dataclass(frozen=True, slots=True)
class _SourceOwnerObligation:
    """Raw-fact catalogue entry, frozen before the corresponding build exists."""
    values: MappingProxyType
    profile_id: str
    owner_kind: str
    structural_states: tuple[tuple[str, str], ...]
    atomic_inventory: tuple[tuple[str, str, tuple[object, ...]], ...]
    freeze_digest: bytes = b""

    def __post_init__(self) -> None:
        if (type(self.values) is not MappingProxyType or not self.profile_id or not self.owner_kind
                or not self.structural_states or not self.atomic_inventory):
            raise ValueError("source owner obligation closure")
        names = tuple(item[0] for item in self.atomic_inventory)
        if len(names) != len(set(names)) or tuple(sorted(names)) != names:
            raise ValueError("source owner obligation closure")
        arena, _ref_ids, base_state = _private_owner_arena(sealed=False)
        if any(
                type(name) is not str or not name or type(state) is not str
                or _compact_dependency_metadata(descriptor, arena, base_state) is None
                for name, state, descriptor in self.atomic_inventory
        ):
            raise ValueError("source owner obligation closure")
        object.__setattr__(self, "freeze_digest", _owner_inventory_digest(
            self.profile_id, self.owner_kind, self.structural_states, self.atomic_inventory,
        ))


def _freeze_source_owner(values: MappingProxyType, profile: str, owner: str,
                         structural_states: tuple[tuple[str, str], ...],
                         atomic_inventory: tuple[tuple[str, str, tuple[object, ...]], ...]) -> _SourceOwnerObligation:
    """Detach one validated source catalogue entry from every mutable build path."""
    return _SourceOwnerObligation(
        MappingProxyType(dict(values)), profile, owner, structural_states, atomic_inventory,
    )


# One sealed private dependency plan shared by P7 and public materialization is
# the primitive 5-tuple (arena, fields, range_fields, field_metadata,
# range_metadata); every node of it is an exact tuple of scalars or tuples.


def _private_owner_arena(*, sealed: bool):
    """Read the one call-scoped private arena without copying it into an owner."""
    context = _P5_REF_ARENA_CONTEXT.get()
    if type(context) is not tuple:
        raise ValueError("private atom arena required")
    if sealed:
        # A sealed context is (arena, immutable state) only: the pre-seal atom→ID
        # reverse index must be unreachable, and a live one is rejected outright.
        if len(context) != 2:
            raise ValueError("owner compact dependency closure")
        arena, bases = context
        if type(arena) is not tuple or type(bases) is not tuple:
            raise ValueError("owner compact dependency closure")
        # This is the one full sealed-authority validation.  Downstream plan,
        # P7, and public-materialization functions receive this exact immutable
        # pair explicitly and never reread the ContextVar.
        try:
            if any(_private_source_identity(identity) != identity for identity in arena):
                raise ValueError("owner atomic arena closure")
        except ValueError as error:
            raise ValueError("owner atomic arena closure") from error
        if any(
            type(entry) is not tuple or len(entry) != 4
            or type(entry[0]) is not tuple
            or type(entry[1]) is not int or isinstance(entry[1], bool) or entry[1] < 0
            or type(entry[2]) is not tuple or len(entry[2]) != 4
            or any(type(part) is not int or isinstance(part, bool) or part < 0 for part in entry[2])
            or type(entry[3]) is not int or isinstance(entry[3], bool) or entry[3] < 0
            or entry[1] != len(entry[0])
            or tuple(sorted(entry[0])) != entry[0] or len(entry[0]) != len(set(entry[0]))
            or any(type(ref_id) is not int or isinstance(ref_id, bool) or ref_id < 0 or ref_id >= len(arena)
                   for ref_id in entry[0])
            for entry in bases
        ):
            raise ValueError("owner compact dependency closure")
        if any(
            (entry[1], entry[2], entry[3]) != _compact_base_metadata(arena, entry[0])
            for entry in bases
        ):
            raise ValueError("owner compact dependency closure")
        return arena, bases
    if len(context) != 3:
        raise ValueError("private atom arena required")
    arena, ref_ids, state = context
    if (type(arena) is not tuple or type(ref_ids) is not MappingProxyType or type(state) is not dict
            or state.get("dynamic") is True
            or type(state.get("owner_seals")) is not dict):
        raise ValueError("owner atomic arena closure")
    if not state.get("arena_validated"):
        # The arena/ref-index pair is constructed once per call and immutable;
        # the full cross-validation runs once per state, not per owner build.
        if (any(type(ref) is not _EvidenceAtom for ref in arena)
                or tuple(sorted(arena, key=lambda ref: _source_cells_key((ref,)))) != arena
                or len(arena) != len(set(arena))
                or any(ref_ids.get(ref) != index for index, ref in enumerate(arena))
                or len(ref_ids) != len(arena)):
            raise ValueError("owner atomic arena closure")
        state["arena_validated"] = True
    return arena, ref_ids, MappingProxyType(state)


def _owner_inventory_digest(profile: str, owner: str, states: tuple[tuple[str, str], ...],
                            inventory: tuple[tuple[str, str, tuple[object, ...]], ...]) -> bytes:
    """Seal owner-local descriptors in the call arena without mirroring its refs."""
    return sha256(repr((profile, owner, states, inventory)).encode("utf-8")).digest()


def _verify_owner_inventory_seal(build: _OwnerBuildState) -> None:
    """Reject post-freeze descriptor mutation before any phase can materialize it."""
    if build.freeze_digest != _owner_inventory_digest(
            build.profile_id, build.owner_kind, build.structural_states, build.atomic_inventory,
    ):
        raise ValueError("owner dependency compact inventory closure")



def _a1(row: int, column: int) -> str:
    letters = ""
    while column:
        column, rem = divmod(column - 1, 26)
        letters = chr(65 + rem) + letters
    return letters + str(row)


def _coordinate(ref: str) -> tuple[int, int] | None:
    match = _A1.fullmatch(ref)
    if match is None:
        return None
    column = 0
    for letter in match.group(1):
        column = column * 26 + ord(letter) - 64
    return int(match.group(2)), column


def _header(value: object) -> str:
    if type(value) is _Cell:
        if value.casefolded_text is None:
            return ""
        return " ".join(value.casefolded_text.replace("\r\n", "\n").replace("\r", "\n").split())
    if type(value) is not str:
        return ""
    return " ".join(value.replace("\r\n", "\n").replace("\r", "\n").split()).casefold()


def _header_state(cell: _Cell | None, cells: tuple[_Cell, ...]) -> str:
    if cell is None:
        return "BLANK_HEADER"
    if cell.formula is not None:
        return "FORMULA_HEADER"
    if any(
        (item.row, item.column) != (cell.row, cell.column)
        and (item.sheet_ref, item.authority_row, item.authority_column)
        == (cell.sheet_ref, cell.authority_row, cell.authority_column)
        for item in cells
    ):
        return "MERGED_HEADER"
    if cell.value is None or type(cell.value) is str and not _header(cell):
        return "BLANK_HEADER"
    return "TOKEN_HEADER" if type(cell.value) is str else "UNKNOWN_HEADER"


def _structural(cell: _Cell) -> bool:
    return cell.formula is not None or cell.value not in (None, "")


def _sheet_key(normalized_casefold: str) -> str:
    return normalized_casefold.strip()


def _ref(cell: _Cell) -> _EvidenceAtom:
    return _EvidenceAtom(cell.sheet_ref, cell.row, cell.column, cell.ref, cell.authority_row, cell.authority_column, cell.authority_ref, cell.value_origin)


def _refs(*cells: _Cell | None) -> tuple[_EvidenceAtom, ...]:
    values = {_ref(cell) for cell in cells if cell is not None}
    return tuple(sorted(values, key=lambda x: (x.sheet_ref, x.row_index, x.column_index, x.authority_row_index, x.authority_column_index, x.value_origin, x.cell_ref)))


def _p5_owner_descriptor(kind: int, owner_field: str, owner: _Cell, cells: tuple[_Cell, ...],
                         authority_cells: Mapping[tuple[str, int, int], tuple[_Cell, ...]] | None = None) -> tuple[int, int, int, int, int, int, int, int, int]:
    if authority_cells is not None:
        members = authority_cells.get((owner.sheet_ref, owner.authority_row, owner.authority_column), ())
    else:
        members = tuple(cell for cell in cells if (cell.sheet_ref, cell.authority_row, cell.authority_column) == (owner.sheet_ref, owner.authority_row, owner.authority_column))
    if not members:
        raise ValueError("missing provisional owner")
    return (kind, int(owner.sheet_ref[1:]), owner.authority_row, owner.authority_column,
            min(cell.row for cell in members), min(cell.column for cell in members),
            max(cell.row for cell in members), max(cell.column for cell in members), _FIELD_ORDINAL[owner_field])


def _p5_provisional_scopes(descriptors: tuple[tuple[int, int, int, int, int, int, int, int, int], ...]) -> dict[tuple[int, int, int, int, int, int, int, int, int], tuple[int, int, int, int, int]]:
    ordered = tuple(sorted(set(descriptors)))
    return {descriptor: (descriptor[1], descriptor[2], descriptor[3], descriptor[0], ordinal + 1)
            for ordinal, descriptor in enumerate(ordered)}


def _range(refs: tuple[SourceCellRefV1, ...]) -> SourceRangeV1:
    rows = [x.row_index for x in refs] + [x.authority_row_index for x in refs]
    columns = [x.column_index for x in refs] + [x.authority_column_index for x in refs]
    return SourceRangeV1(refs[0].sheet_ref, min(rows), min(columns), max(rows), max(columns), _a1(min(rows), min(columns)), _a1(max(rows), max(columns)))


def _provenance(items: dict[str, tuple[str, tuple[SourceCellRefV1, ...]]]) -> tuple[FieldProvenanceV1, ...]:
    return tuple(FieldProvenanceV1(name, refs, rule) for name, (rule, refs) in sorted(items.items()))


